/**
 * Calm sounds. Every file is generated by scripts/generate-sounds.sh from
 * filtered noise, tones and timed events — no recordings, so there are no
 * licences to track — and each is a seamless loop, bundled with the app so it
 * plays offline.
 *
 * Café and Morning Birds are wanted too, but voices and birdsong need real
 * recordings; they are added when licence-clean ones are found.
 */

export type Sound = {
  key: string;
  name: string;
  /** One line under the name. */
  note: string;
  asset: number;
};

export type SoundCategory = {
  key: string;
  label: string;
  sounds: readonly Sound[];
};

