export const ALL_SOUNDS: readonly Sound[] = SOUND_CATEGORIES.flatMap(c => c.sounds);

/** The two player settings the calm sounds change. */
type Settable = { loop: boolean; volume: number };

/**
 * Sets them on an expo-audio player. Kept out of the component because the
 * player is a hook's return value, which React's rules treat as read-only
 * there — though the native player is designed to be set like this.
 */
export function configure(player: Settable, settings: Partial<Settable>): void {
  if (settings.loop !== undefined) player.loop = settings.loop;
  if (settings.volume !== undefined) player.volume = settings.volume;
}

/** Sleep timer choices, in minutes; null runs until stopped. */
export const TIMER_CHOICES = [null, 15, 30, 60] as const;
export type TimerChoice = (typeof TIMER_CHOICES)[number];

/** When a sleep timer set at `from` ends; null for no timer. */
export function timerEndsAt(choice: TimerChoice, from: number = Date.now()): number | null {
  return choice === null ? null : from + choice * 60_000;
}

/** How long the fade at the end of a sleep timer lasts. */
export const FADE_MS = 10_000;

/** Volume `elapsedMs` into the closing fade: 1 → 0 along a gentle curve. */
export function fadeVolume(elapsedMs: number): number {
  const x = Math.min(1, Math.max(0, elapsedMs / FADE_MS));
  return Math.cos((x * Math.PI) / 2) ** 2;
}
